var Search=(function(){var fuse;var index=[];var options={shouldSort:!0,threshold:0.6,location:0,distance:100,maxPatternLength:32,minMatchCharLength:1,keys:["fqsen","name","summary","url"]};function debounce(func,wait,immediate){var timeout;return function executedFunction(){var context=this;var args=arguments;var later=function(){timeout=null;if(!immediate)func.apply(context,args);};var callNow=immediate&&!timeout;clearTimeout(timeout);timeout=setTimeout(later,wait);if(callNow)func.apply(context,args);}}
function close(){const scrollY=document.body.style.top;document.body.style.position='';document.body.style.top='';window.scrollTo(0,parseInt(scrollY||'0')*-1);var form=document.querySelector('[data-search-form]');var searchResults=document.querySelector('[data-search-results]');form.classList.toggle('phpdocumentor-search--has-results',!1);searchResults.classList.add('phpdocumentor-search-results--hidden');var searchField=document.querySelector('[data-search-form] input[type="search"]');searchField.blur()}
function search(event){document.body.style.position='fixed';document.body.style.top=`-${window.scrollY}px`;event.stopPropagation();var form=document.querySelector('[data-search-form]');var searchResults=document.querySelector('[data-search-results]');var searchResultEntries=document.querySelector('[data-search-results] .phpdocumentor-search-results__entries');searchResultEntries.innerHTML='';if(!event.target.value){close();return}
form.classList.toggle('phpdocumentor-search--has-results',!0);searchResults.classList.remove('phpdocumentor-search-results--hidden');var results=fuse.search(event.target.value,{limit:25});results.forEach(function(result){var entry=document.createElement("li");entry.classList.add("phpdocumentor-search-results__entry");entry.innerHTML+='<h3><a href="'+document.baseURI+result.url+'">'+result.name+"</a></h3>\n";entry.innerHTML+='<small>'+result.fqsen+"</small>\n";entry.innerHTML+='<div class="phpdocumentor-summary">'+result.summary+'</div>';searchResultEntries.appendChild(entry)})}
function appendIndex(added){index=index.concat(added);if(typeof fuse!=='undefined'){fuse=new Fuse(index,options)}}
function init(){fuse=new Fuse(index,options);var form=document.querySelector('[data-search-form]');var searchField=document.querySelector('[data-search-form] input[type="search"]');var closeButton=document.querySelector('.phpdocumentor-search-results__close');closeButton.addEventListener('click',function(){close()}.bind(this));var searchResults=document.querySelector('[data-search-results]');searchResults.addEventListener('click',function(){close()}.bind(this));form.classList.add('phpdocumentor-search--active');searchField.setAttribute('placeholder','Search (Press "/" to focus)');searchField.removeAttribute('disabled');searchField.addEventListener('keyup',debounce(search,300));window.addEventListener('keyup',function(event){if(event.key==='/'){searchField.focus()}
if(event.code==='Escape'){close()}}.bind(this))}
return{appendIndex,init}})();window.addEventListener('DOMContentLoaded',function(){var form=document.querySelector('[data-search-form]');form.classList.add('phpdocumentor-search--enabled')});window.addEventListener('load',function(){Search.init()})
